System.out.println("=== GROUP BY user_id + COUNT(*) ===");
print(stmt.executeQuery("""
    SELECT user_id, COUNT(*) AS liczba_zamowien
    FROM orders
    GROUP BY user_id
    """));
// Kazdy user_id trafia do osobnej grupy - COUNT(*) liczy, ile wierszy
// (zamowien) znalazlo sie w kazdej grupie.
// WAZNE: w SELECT razem z funkcja agregujaca mozna podac TYLKO kolumny,
// po ktorych grupujemy - SQL nie pozwoli wybrac np. 'amount' bez agregacji.

System.out.println("=== GROUP BY user_id + SUM/AVG/MIN/MAX ===");
print(stmt.executeQuery("""
    SELECT user_id,
           SUM(amount) AS suma,
           AVG(amount) AS srednia,
           MIN(amount) AS minimalna,
           MAX(amount) AS maksymalna
    FROM orders
    GROUP BY user_id
    """));
// Wszystkie funkcje agregujace mozna laczyc w jednym zapytaniu naraz,
// kazda liczy inna statystyke z TEJ SAMEJ grupy wierszy.

System.out.println("=== HAVING COUNT(*) > 1 ===");
print(stmt.executeQuery("""
    SELECT user_id, COUNT(*) AS liczba_zamowien
    FROM orders
    GROUP BY user_id
    HAVING COUNT(*) > 1
    """));
// HAVING dziala PO GROUP BY - moze uzywac COUNT(*)/SUM(...)/AVG(...)
// wprost w warunku, bo w tym momencie agregaty juz ISTNIEJA.

System.out.println("=== WHERE + GROUP BY + HAVING ===");
print(stmt.executeQuery("""
    SELECT user_id, SUM(amount) AS suma
    FROM orders
    WHERE amount > 20
    GROUP BY user_id
    HAVING SUM(amount) > 100
    """));
// Kolejnosc LOGICZNEGO wykonania: najpierw WHERE (filtruje pojedyncze
// wiersze), potem GROUP BY (grupuje to, co zostalo), potem HAVING
// (filtruje gotowe grupy).
